# Presentation metadata; complete original project descriptions remain on detail pages.
titles = ['EVOSST','TwinEU','ELECTRON','INTERRFACE','FARCROSS','FLEXITRANSTORE','VIRPRO','Biomonitorizarea parametrilor vitali','ENOPT','Parcuri eoliene la cheie','UAS BIRD','TEHNO-S','Monitorizarea la distanță a ECG','Corecția erorilor de măsurare a energiei','SINGULAR','HERMES','South-East European TSO Challenges','EVOSST Energy Index','Resilient nanogrids','Semafor inteligent cu LED','Izolatoare din materiale compozite','Inspecția infrastructurilor critice','SIMCEC','Resurse regenerabile insulare','NANOLASCAN','MOIST','SigMED','Mecanisme energetice sud-europene','VIDEOCAL','ERISC','OFTALAS','MMS','SIASTE','RELES','MS-FORTE','ISCET','MAST','AVION','SIMT','INTIL','IFIPVCELLS','PROLOG','Surse statice pentru aeronave','Laborator pentru calitatea energiei','Nanometrologia microsistemelor','Iluminat public cu perturbații reduse','Măsurarea expandării țevilor','Caracterizarea contoarelor digitale','Centru de pregătire PHARE']
summaries = ['Evaluarea și valorificarea serviciilor sociale pentru o tranziție sustenabilă.','Un geamăn digital al sistemului electroenergetic european.','Reziliență și autorestabilire în nanorețele electrice.','Coordonarea operatorilor de transport, distribuție și a consumatorilor prin servicii interoperabile.','Transferuri transfrontaliere de energie, observabilitate și coordonare regională.','Flexibilitate, stocare și integrarea surselor regenerabile în rețelele de transport.','Platformă virtuală de e-learning cu aplicații 3D pentru protetica dentară.','Monitorizarea parametrilor vitali în operarea infrastructurilor critice.','Optimizarea și eficientizarea consumurilor energetice la întreprinderile mici și mijlocii.','Integrarea fabricării stâlpilor și asamblării turbinelor în construcția parcurilor eoliene.','Monitorizarea cu sisteme aeriene fără pilot a păsărilor din Delta Dunării.','Parteneriate și participare la cercetarea europeană în tehnologii de mediu, alimentație și sănătate.','Monitorizare și analiză la distanță a parametrilor ECG pentru creșterea calității vieții.','Corecția automată a erorilor de măsurare în regimuri permanente și tranzitorii.','Rețele electrice insulare inteligente și sustenabile, cu integrare extinsă a regenerabilelor.','Măsurarea și controlul eficient al suprafețelor rutiere.','Provocări ale operatorilor de transport din sud-estul Europei.','Evaluarea multicriterială a consumului casnic de electricitate și recomandări de eficiență energetică.','Sprijin național pentru cercetarea nanorețelelor electrice reziliente și autorecuperabile.']
periods=['2025–2028','2024–2026','2021–2024','2019–2023','2019–2023','2017–2021','2014–2017','2014–2016','2013–2015','2013–2015','2012–2013','2006–2008','2004','1999–2000','2012–2015','2012–2014','2010–2012','Octombrie 2025 – iunie 2027','Octombrie 2022 – septembrie 2024','2016–2018','2016–2018','Contract din 2016','2014–2017','2013–2015','2012–2015','2012–2015','2012–2015','2010–2012','2008–2011','2008–2011','2008–2010','2008–2010','2008–2010','2007–2010','2007–2009','2007–2009','2007–2009','2007–2009','2007–2009','2007–2009','2007–2009','2007–2009','2006–2007','2006–2007','2005–2007','2003–2005','2003–2005','2000–2002','2000']
slugs=['evosst','twineu','electron','interrface','farcross','flexitranstore']+[f'proiect-{i+1:02}' for i in range(6,len(projects))]
slugs[17:19]=['evosst-energy-index','nanogrids']
assert len(titles)==len(periods)==len(projects)==49
projecthtml=''
for group in dict.fromkeys(r['category'] for r in projects):
 role='Director / responsabil' if 'director' in group else 'Membru în echipă'
 scope='Internațional' if group.startswith('interna') else 'Național'
 label=('Internaționale' if scope=='Internațional' else 'Naționale')+' – '+role.lower().replace(' / ','/')
 projecthtml+=f'<h2 class="project-group">{esc(label)}</h2><div class="project-grid">'
 for i,r in enumerate(projects):
  if r['category']!=group: continue
  title=titles[i];slug=slugs[i];url=f'project-{slug}.html';raw=r['text']
  summary=summaries[i] if i<len(summaries) else re.split(r',?\s*(?:Contract|contract|nr\.|Nr\.|PNCDI|AMCSIT|PARTENERIATE)',raw)[0].strip(' „“;,.')
  if not summary: summary=title
  director=' director' if 'director' in group else ''
  projecthtml+=f'<article class="project-card{director}"><p class="eyebrow">{scope} · Cercetare</p><h3 class="project-title"><a href="{url}">{esc(title)}</a></h3><p>{esc(summary)}</p><div class="project-meta"><strong>{role}</strong><span>{periods[i]}</span></div><a class="text-link" href="{url}">Detalii proiect →</a></article>'
  if slug in ('farcross','interrface'): continue
  full=esc(raw);full=re.sub(r'(https?://[^\s<>]+)',r'<a href="\1">\1</a>',full)
  facts=f'<dt>Participare</dt><dd>{role}</dd><dt>Categorie</dt><dd>{scope}</dd><dt>Interval raportat</dt><dd>{periods[i]}</dd>'
  if i==17: facts+='<dt>Instituție</dt><dd>Universitatea Națională de Știință și Tehnologie POLITEHNICA București</dd><dt>Finanțare</dt><dd>UEFISCDI · PNCDI IV · Premiere Orizont Europa – Instituții</dd><dt>Contract</dt><dd>121PHE/2025</dd><dt>Buget</dt><dd>104.500 lei · buget de stat · fără cofinanțare</dd>'
  if i==18: facts+='<dt>Instituție</dt><dd>Universitatea POLITEHNICA din București</dd><dt>Finanțare</dt><dd>PN III · Premiere Orizont 2020</dd><dt>Contract</dt><dd>72 / 03.10.2022</dd><dt>Buget</dt><dd>112.303 lei (aproximativ 23.000 EUR)</dd>'
  page('project-'+slug,title,intro(title,summary,scope+' · Proiect de cercetare')+'<div class="wrap breadcrumb"><a href="research.html#projects">← Înapoi la proiecte</a></div><section class="section wrap project-detail"><div class="prose"><h2>Descriere și identificare</h2><p>'+full+'</p><h2>Participare</h2><p>George-Călin Serițan · '+role+'</p><p class="figure-note">Intervalul raportat este păstrat conform informațiilor furnizate. Durata proiectului nu reprezintă automat durata unei numiri individuale.</p></div><aside class="fact-panel"><dl>'+facts+'</dl></aside></section>')
 projecthtml+='</div>'
flow='<section class="wrap section"><div class="research-flow">'+''.join(f'<div><span>{a}</span><strong>{b}</strong><span>{c}</span></div>' for a,b,c in [('01 / Observare','Măsurare și caracterizare','Mărimi electrice, semnale și condiții de funcționare.'),('02 / Înțelegere','Modelare și interpretare','Metrologie, incertitudine și prelucrarea datelor.'),('03 / Aplicare','Sisteme și decizii','Rețele inteligente, energie și instrumentație biomedicală.')])+'</div></section>'
page('research','Cercetare',intro('Cercetare conectată cu aplicațiile.','Proiecte de metrologie, energie și instrumentație: coordonare și colaborare în cercetarea națională și internațională.','Portofoliu de cercetare')+flow+'<section id="projects" class="section wrap"><div class="section-head"><div><p class="eyebrow">Proiecte de cercetare</p><h2>Portofoliul complet</h2></div><span class="figure-note">49 de proiecte</span></div><p class="figure-note">Rolurile și perioadele sunt redate conform informațiilor profesionale furnizate. Durata proiectului și perioada participării individuale sunt indicate separat acolo unde sunt disponibile.</p>'+projecthtml+'<h2 class="project-group">Proprietate industrială</h2>'+''.join('<p>'+esc(r['text'])+'</p>' for r in records if r['section']=='D')+'</section>')
